# -*- coding: utf-8 -*-
"""g11-stats-01 = Toán 11 KNTT, Bài 8: Mẫu số liệu ghép nhóm. Mã ngân hàng câu hỏi: TOAN11-C3-B08."""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'tools'))
from mb_quick import *
import sp_g11

CV = 'Mẫu số liệu ghép nhóm'
vocab = defs(CV, [
 ('grouped', 'grouped data', 'mẫu số liệu ghép nhóm', 'data put into groups (intervals) instead of single values.', 'mẫu số liệu được chia thành các nhóm (khoảng) thay vì giá trị riêng lẻ.', 'The grouped data show students’ heights.', ''),
 ('group', 'group (class)', 'nhóm số liệu', 'one interval of the data, such as \\([10;20)\\).', 'một khoảng của số liệu, chẳng hạn \\([10;20)\\).', 'The first group is \\([0;10)\\).', '\\([a;b)\\)'),
 ('freq', 'frequency', 'tần số', 'the number of data values in a group.', 'số giá trị của mẫu số liệu thuộc một nhóm.', 'The frequency of this group is 7.', '\\(n_i\\)'),
 ('relfreq', 'relative frequency', 'tần suất', 'frequency divided by the total, often in percent.', 'tần số chia cho tổng số giá trị, thường viết bằng phần trăm.', 'The relative frequency is 25 percent.', '\\(f_i\\)'),
 ('freqtable', 'frequency table', 'bảng tần số', 'a table showing each group and its frequency.', 'bảng ghi mỗi nhóm và tần số của nhóm đó.', 'Make a frequency table.', ''),
 ('midpoint', 'midpoint (representative value)', 'giá trị đại diện', 'the middle of a group: \\(\\dfrac{a+b}{2}\\).', 'giá trị chính giữa của nhóm: \\(\\dfrac{a+b}{2}\\).', 'The midpoint of [10; 20) is 15.', '\\(x_i\\)'),
 ('cumul', 'cumulative frequency', 'tần số tích lũy', 'the number of values up to the end of a group.', 'số giá trị từ nhóm đầu đến hết nhóm đang xét.', 'Write the cumulative frequency.', ''),
 ('histogram', 'histogram', 'biểu đồ cột (biểu đồ tần số)', 'a chart with bars for each group.', 'biểu đồ có một cột cho mỗi nhóm.', 'Read the histogram.', ''),
 ('sample', 'sample size', 'cỡ mẫu', 'the total number of data values, \\(n\\).', 'tổng số giá trị của mẫu số liệu, \\(n\\).', 'The sample size is 40.', '\\(n\\)')])
goals = [('recognise grouped data, groups, frequencies and relative frequencies;', 'nhận biết [[mẫu số liệu ghép nhóm]], [[nhóm số liệu]], [[tần số]], [[tần suất]];'), ('make a [[frequency table]] and a cumulative table;', 'lập [[bảng tần số]] và bảng tần số tích lũy;'), ('read a histogram and find the midpoint of a group;', 'đọc [[biểu đồ cột (biểu đồ tần số)]] và tìm [[giá trị đại diện]] của nhóm;'), ('describe real data in simple English.', 'nhận xét số liệu thực tế bằng tiếng Anh đơn giản.')]
goals[1] = ('make a frequency table and a cumulative table;', 'lập [[bảng tần số]] và bảng [[tần số tích lũy]];')
phrases = [('<b>Make a frequency table.</b>', 'Lập bảng tần số.'), ('<b>Which group has the highest frequency?</b>', 'Nhóm nào có tần số lớn nhất?'), ('<b>How many values are less than 20?</b>', 'Có bao nhiêu giá trị nhỏ hơn 20?'), ('<b>the percentage of students</b>', 'tỉ lệ phần trăm học sinh')]
review = T('A data value is a number we measure, for example a height. To read a table, find the group first and then its frequency.', 'Giá trị số liệu là số ta đo được, chẳng hạn chiều cao. Để đọc bảng, tìm nhóm trước rồi đọc tần số của nhóm.')
tabrows = [['\\([0;10)\\)', '4', '\\(5\\%\\)', '4'], ['\\([10;20)\\)', '12', '\\(15\\%\\)', '16'], ['\\([20;30)\\)', '40', '\\(50\\%\\)', '56'], ['\\([30;40)\\)', '24', '\\(30\\%\\)', '80']]
assert 4 + 12 + 40 + 24 == 80 and [100 * x // 80 for x in (4, 12, 40, 24)] == [5, 15, 50, 30]
theory = '<h3>5.1 %s</h3>' % TI('Grouped data', 'Mẫu số liệu ghép nhóm')
theory += BOX('blue', ('Definition', 'Định nghĩa'), T('When there are many different values, we divide them into <b>groups</b> \\([a_1;a_2),[a_2;a_3),\\dots\\) of equal width. The <b>frequency</b> \\(n_i\\) of a group is the number of values in it. The total \\(n=n_1+n_2+\\dots\\) is the <b>sample size</b>.', 'Khi có nhiều giá trị khác nhau, ta chia chúng thành các [[nhóm số liệu]] \\([a_1;a_2),[a_2;a_3),\\dots\\) có độ rộng bằng nhau. [[Tần số]] \\(n_i\\) của một nhóm là số giá trị thuộc nhóm; tổng \\(n=n_1+n_2+\\dots\\) là [[cỡ mẫu]].'), T('A value equal to the right end \\(a_{i+1}\\) goes to the next group.', 'Giá trị bằng đầu mút phải \\(a_{i+1}\\) được xếp vào nhóm kế tiếp.'))
theory += '<h3>5.2 %s</h3>' % TI('Frequency tables', 'Bảng tần số, tần suất và tần số tích lũy')
theory += BOX('mint', ('Formulas', 'Công thức'), M('f_i=\\dfrac{n_i}{n}\\cdot100\\%'), T('The <b>cumulative frequency</b> of a group is \\(n_1+\\dots+n_i\\): the number of values smaller than the right end of the group.', '[[Tần số tích lũy]] của một nhóm là \\(n_1+\\dots+n_i\\): số giá trị nhỏ hơn đầu mút phải của nhóm đó.'))
from freqtable import FREQ
theory += T(FREQ([0, 10, 20, 30, 40], [4, 12, 40, 24], rows=('group', 'mid', 'freq', 'rel', 'cum'), lang='en'), FREQ([0, 10, 20, 30, 40], [4, 12, 40, 24], rows=('group', 'mid', 'freq', 'rel', 'cum'), lang='vi'))
theory += '<h3>5.3 %s</h3>' % TI('Midpoints and histograms', 'Giá trị đại diện và biểu đồ cột')
theory += BOX('blue', ('Midpoint', 'Giá trị đại diện'), T('The <b>midpoint</b> of \\([a;b)\\) is \\(x=\\dfrac{a+b}{2}\\). It stands for all values in the group when we need one number. In a <b>histogram</b>, the height of each bar is the frequency (or relative frequency) of its group.', '[[Giá trị đại diện]] của nhóm \\([a;b)\\) là \\(x=\\dfrac{a+b}{2}\\); dùng khi cần một số thay cho cả nhóm. Trong [[biểu đồ cột (biểu đồ tần số)]], chiều cao mỗi cột là tần số (hoặc tần suất) của nhóm.'))
theory += BOX('yellow', ('Watch out!', 'Lưu ý'), T('Groups must not overlap and must cover all the data. The relative frequencies add up to \\(100\\%\\).', 'Các nhóm không được chồng lên nhau và phải phủ hết số liệu. Các tần suất cộng lại bằng \\(100\\%\\).'))
raw = [3, 7, 12, 14, 15, 18, 21, 22, 24, 25, 27, 29, 31, 33, 35, 38]
cnt = [sum(1 for v in raw if lo <= v < lo + 10) for lo in (0, 10, 20, 30)]; assert cnt == [2, 4, 6, 4] and sum(cnt) == len(raw)
examples = EXAMPLE(1, ('Basic', 'Cơ bản'), ('Groups and midpoints', 'Nhóm và giá trị đại diện'), T('Heights (cm) are grouped as \\([150;155),[155;160),[160;165),[165;170)\\). Find the width and the midpoint of each group.', 'Chiều cao (cm) chia thành các nhóm \\([150;155),[155;160),[160;165),[165;170)\\). Tìm độ rộng và giá trị đại diện của mỗi nhóm.'), ('Width \\(=b-a\\); midpoint \\(=\\dfrac{a+b}{2}\\).', 'Độ rộng \\(=b-a\\); giá trị đại diện \\(=\\dfrac{a+b}{2}\\).'), [T('Every group has width \\(5\\).', 'Mỗi nhóm có độ rộng \\(5\\).'), T('Midpoints: \\(152.5;\\ 157.5;\\ 162.5;\\ 167.5\\).', 'Giá trị đại diện: \\(152{,}5;\\ 157{,}5;\\ 162{,}5;\\ 167{,}5\\).')], T('Width 5; midpoints \\(152.5,157.5,162.5,167.5\\).', 'Độ rộng 5; giá trị đại diện \\(152{,}5;\\ 157{,}5;\\ 162{,}5;\\ 167{,}5\\).'))
examples += EXAMPLE(2, ('Basic', 'Cơ bản'), ('Make a frequency table', 'Lập bảng tần số'), T('Test scores of 16 students: \\(3,7,12,14,15,18,21,22,24,25,27,29,31,33,35,38\\). Group them as \\([0;10),[10;20),[20;30),[30;40)\\).', 'Điểm của 16 học sinh: \\(3,7,12,14,15,18,21,22,24,25,27,29,31,33,35,38\\). Chia thành các nhóm \\([0;10),[10;20),[20;30),[30;40)\\).'), ('Count the values in each group.', 'Đếm số giá trị trong mỗi nhóm.'), [T('\\([0;10)\\): 3, 7 → 2 values. \\([10;20)\\): 12, 14, 15, 18 → 4.', '\\([0;10)\\): 3, 7 → 2 giá trị. \\([10;20)\\): 12, 14, 15, 18 → 4.'), T('\\([20;30)\\): 21, 22, 24, 25, 27, 29 → 6. \\([30;40)\\): 31, 33, 35, 38 → 4. Total \\(16\\).', '\\([20;30)\\): 21, 22, 24, 25, 27, 29 → 6. \\([30;40)\\): 31, 33, 35, 38 → 4. Tổng \\(16\\).')], T('Frequencies \\(2,4,6,4\\).', 'Các tần số \\(2,4,6,4\\).'))
examples += EXAMPLE(3, ('Intermediate', 'Trung bình'), ('Relative frequency', 'Tần suất'), T('Use the table of Example 2. Find the relative frequency of each group and the percentage of students with a score below 20.', 'Dùng bảng ở Ví dụ 2. Tính tần suất của mỗi nhóm và tỉ lệ học sinh có điểm dưới 20.'), ('\\(f_i=\\dfrac{n_i}{16}\\cdot100\\%\\).', '\\(f_i=\\dfrac{n_i}{16}\\cdot100\\%\\).'), [T('\\(12.5\\%,\\ 25\\%,\\ 37.5\\%,\\ 25\\%\\).', '\\(12{,}5\\%;\\ 25\\%;\\ 37{,}5\\%;\\ 25\\%\\).'), T('Below 20: \\(2+4=6\\) students, \\(\\dfrac{6}{16}=37.5\\%\\).', 'Dưới 20: \\(2+4=6\\) học sinh, \\(\\dfrac{6}{16}=37{,}5\\%\\).')], T('37.5% of students scored below 20.', '37,5% học sinh có điểm dưới 20.'))
assert [100 * c / 16 for c in cnt] == [12.5, 25.0, 37.5, 25.0]
examples += EXAMPLE(4, ('Intermediate', 'Trung bình'), ('Cumulative frequency', 'Tần số tích lũy'), T('A table has groups \\([0;5),[5;10),[10;15),[15;20)\\) with frequencies \\(3,8,10,4\\). Find the cumulative frequencies. How many values are less than 15?', 'Bảng có các nhóm \\([0;5),[5;10),[10;15),[15;20)\\) với tần số \\(3,8,10,4\\). Tìm tần số tích lũy. Có bao nhiêu giá trị nhỏ hơn 15?'), ('Add the frequencies one by one.', 'Cộng dồn các tần số.'), [T('Cumulative: \\(3,\\ 11,\\ 21,\\ 25\\).', 'Tần số tích lũy: \\(3,\\ 11,\\ 21,\\ 25\\).'), T('Values less than 15: the cumulative frequency of \\([10;15)\\), which is \\(21\\).', 'Số giá trị nhỏ hơn 15 là tần số tích lũy của nhóm \\([10;15)\\), bằng \\(21\\).')], T('21 values.', '21 giá trị.'))
assert [sum([3, 8, 10, 4][:i + 1]) for i in range(4)] == [3, 11, 21, 25]
examples += EXAMPLE(5, ('Advanced', 'Nâng cao'), ('Describe real data', 'Nhận xét số liệu thực tế'), T('Daily study time (minutes) of 40 students: \\([0;30)\\): 4, \\([30;60)\\): 12, \\([60;90)\\): 16, \\([90;120)\\): 8. Find the group with the highest frequency, the percentage studying 60 minutes or more, and write one sentence in English.', 'Thời gian tự học mỗi ngày (phút) của 40 học sinh: \\([0;30)\\): 4, \\([30;60)\\): 12, \\([60;90)\\): 16, \\([90;120)\\): 8. Tìm nhóm có tần số lớn nhất, tỉ lệ học từ 60 phút trở lên và viết một câu nhận xét bằng tiếng Anh.'), ('Highest frequency; add the last two groups.', 'Tần số lớn nhất; cộng hai nhóm cuối.'), [T('Highest frequency: \\([60;90)\\) with 16 students.', 'Tần số lớn nhất: nhóm \\([60;90)\\) với 16 học sinh.'), T('\\(60\\) minutes or more: \\(16+8=24\\) students, \\(\\dfrac{24}{40}=60\\%\\).', 'Từ 60 phút trở lên: \\(16+8=24\\) học sinh, \\(\\dfrac{24}{40}=60\\%\\).'), T('Sample sentence: “Most students study between 60 and 90 minutes a day.”', 'Câu mẫu: “Most students study between 60 and 90 minutes a day.” (Đa số học sinh tự học từ 60 đến 90 phút mỗi ngày.)')], T('Group \\([60;90)\\); 60%.', 'Nhóm \\([60;90)\\); 60%.'))
assert 4 + 12 + 16 + 8 == 40 and (16 + 8) / 40 == .6

def tab(edges, fs):
    from freqtable import FREQ
    return FREQ(edges, fs)
# Hiệu chỉnh 13/11/2026: viết lại toàn bộ bài tập – mỗi mức 15 câu thuộc 15 dạng khác nhau, bảng số liệu đúng ngôn ngữ của mức.
import sp_g11r as RR, sp_g11r2 as R2
practice = RR.assemble(R2.A8, R2.B8, R2.C8, R2.D8, seeds=(801, 802, 803), ctx_factory=RR.stats_ctx)
mistakes = [('<b>Putting a value in the wrong group.</b> A value equal to the right end belongs to the next group.', '<b>Xếp sai nhóm.</b> Giá trị bằng đầu mút phải thuộc nhóm kế tiếp.'), ('<b>Mixing frequency and relative frequency.</b> Relative frequency is a percentage of the total.', '<b>Nhầm tần số với tần suất.</b> Tần suất là phần trăm so với tổng.'), ('<b>Cumulative frequency of the wrong group.</b> “Less than 15” means all groups before 15.', '<b>Sai tần số tích lũy.</b> “Nhỏ hơn 15” nghĩa là cộng mọi nhóm đứng trước 15.'), ('<b>Using an end value as the midpoint.</b> The midpoint is \\(\\dfrac{a+b}{2}\\).', '<b>Dùng đầu mút làm giá trị đại diện.</b> Giá trị đại diện là \\(\\dfrac{a+b}{2}\\).'), ('<b>Groups of different widths.</b> Keep equal widths when drawing a histogram.', '<b>Các nhóm có độ rộng khác nhau.</b> Khi vẽ biểu đồ cột nên giữ độ rộng bằng nhau.')]
summary = [('Grouped data: groups \\([a;b)\\), frequency \\(n_i\\), sample size \\(n\\).', 'Số liệu ghép nhóm: nhóm \\([a;b)\\), tần số \\(n_i\\), cỡ mẫu \\(n\\).'), ('Relative frequency \\(f_i=\\dfrac{n_i}{n}\\cdot100\\%\\); cumulative frequency adds up.', 'Tần suất \\(f_i=\\dfrac{n_i}{n}\\cdot100\\%\\); tần số tích lũy là cộng dồn.'), ('Midpoint \\(x_i=\\dfrac{a+b}{2}\\).', 'Giá trị đại diện \\(x_i=\\dfrac{a+b}{2}\\).'), ('Key English words: grouped data, frequency, relative frequency, histogram.', 'Từ tiếng Anh cần nhớ: grouped data, frequency, relative frequency, histogram.')]
checks = [('I can make a frequency table from data.', 'Tôi lập được bảng tần số từ số liệu.'), ('I can find relative and cumulative frequencies.', 'Tôi tìm được tần suất và tần số tích lũy.'), ('I can find the midpoint of a group.', 'Tôi tìm được giá trị đại diện của nhóm.'), ('I can describe data in a simple English sentence.', 'Tôi nhận xét được số liệu bằng một câu tiếng Anh đơn giản.'), STD_SUMMARY_CHECK_EN()]
